const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var australia = ee.FeatureCollection('FAO/GAUL/2015/level0').filter(ee.Filter.eq('ADM0_NAME', 'Australia'));
  var indonesia = ee.FeatureCollection('FAO/GAUL/2015/level0').filter(ee.Filter.eq('ADM0_NAME', 'Indonesia'));

  var startDate = '2024-10-01';
  var endDate = '2024-10-31';

  // 2. Data Acquisition - Sentinel-5P CO data
  var ausCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .filterDate(startDate, endDate)
    .filterBounds(australia)
    .select('CO_column_number_density');

  var indoCollection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .filterDate(startDate, endDate)
    .filterBounds(indonesia)
    .select('CO_column_number_density');

  // Check collection sizes
  var ausSize = ausCollection.size().getInfo();
  var indoSize = indoCollection.size().getInfo();

  print(`Australia images: ${ausSize}, Indonesia images: ${indoSize}`);

  if (ausSize === 0 || indoSize === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean CO concentration
  var ausMean = ausCollection.mean();
  var indoMean = indoCollection.mean();

  // Reduce regions to get mean values
  var ausStats = ausMean.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: australia,
    scale: 1000,
    maxPixels: 1e9
  });

  var indoStats = indoMean.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: indonesia,
    scale: 1000,
    maxPixels: 1e9
  });

  var ausData = ausStats.getInfo();
  var indoData = indoStats.getInfo();

  var ausCo = ausData.CO_column_number_density;
  var indoCo = indoData.CO_column_number_density;
  var ausCount = ausData.CO_column_number_density_count;
  var indoCount = indoData.CO_column_number_density_count;

  print(`Australia CO: ${ausCo?.toFixed(6) || 'null'}, Pixels: ${ausCount}`);
  print(`Indonesia CO: ${indoCo?.toFixed(6) || 'null'}, Pixels: ${indoCount}`);

  // 4. Validation & Final Answer
  if (ausCount === 0 || indoCount === 0) {
    print("<answer>C2</answer>");
  } else if (ausCo === null || indoCo === null || isNaN(ausCo) || isNaN(indoCo) || 
             ausCo < 0 || indoCo < 0 || ausCo > 0.1 || indoCo > 0.1) {
    print("<answer>C3</answer>");
  } else if (ausCo > indoCo) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
